import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.CjAa9jTu.js";const m=JSON.parse('{"title":"Taller: compilación, programación y validación de firmware","description":"","frontmatter":{},"headers":[],"relativePath":"guide/taller.md","filePath":"guide/taller.md"}'),n={name:"guide/taller.md"};function o(l,a,d,c,s,p){return r(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="taller-compilacion-programacion-y-validacion-de-firmware" tabindex="-1">Taller: compilación, programación y validación de firmware <a class="header-anchor" href="#taller-compilacion-programacion-y-validacion-de-firmware" aria-label="Permalink to &quot;Taller: compilación, programación y validación de firmware&quot;">​</a></h1><h2 id="proposito" tabindex="-1">Propósito <a class="header-anchor" href="#proposito" aria-label="Permalink to &quot;Propósito&quot;">​</a></h2><p>Completar un ciclo de desarrollo sobre <strong>DevLab PY32F003L24D6TR</strong>, desde modificar el código en Arduino IDE hasta comprobar el resultado físico. La plataforma utiliza un núcleo <strong>ARM Cortex-M0+</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Código → Compilación → Firmware → Programación SWD → Ejecución</span></span>
<span class="line"><span>                                                       ↓</span></span>
<span class="line"><span>                              Validación ← Corrección ← Falla</span></span></code></pre></div><h2 id="duracion-y-organizacion" tabindex="-1">Duración y organización <a class="header-anchor" href="#duracion-y-organizacion" aria-label="Permalink to &quot;Duración y organización&quot;">​</a></h2><p>Propuesta de <strong>dos horas</strong>, basada en el material local de preparación del taller CMIC 2026. El horario definitivo depende de la organización del evento. Las herramientas y los programadores deben quedar preparados antes de la sesión.</p><table tabindex="0"><thead><tr><th>Tiempo</th><th>Actividad</th><th>Evidencia de avance</th></tr></thead><tbody><tr><td>0–15 min</td><td>Reconocer placa, alimentación, LED y SWD</td><td>Identificar las cuatro conexiones de programación</td></tr><tr><td>15–30 min</td><td><a href="./cortex-m">Arquitectura, memoria y periféricos</a></td><td>Explicar qué contiene Flash y qué contiene RAM</td></tr><tr><td>30–45 min</td><td>Recorrer Arduino IDE, compilación y carga</td><td>Verificar placa x4 y reloj interno a 24 MHz</td></tr><tr><td>45–65 min</td><td><a href="./../examples/lab01-blink">Lab 1: Blink</a></td><td>Cargar el programa y cambiar el intervalo</td></tr><tr><td>65–80 min</td><td><a href="./compilacion">Análisis de compilación</a></td><td>Identificar tamaños y archivos .elf, .hex y .bin</td></tr><tr><td>80–100 min</td><td><a href="./../examples/lab05-validacion">Lab 5: Falla controlada</a></td><td>Reproducir y explicar el LED apagado</td></tr><tr><td>100–115 min</td><td>Corrección y validación</td><td>Registrar pruebas positiva, negativa y de recuperación</td></tr><tr><td>115–120 min</td><td>Cierre</td><td>Guardar resultados y recuperar la estación</td></tr></tbody></table><p>Las prácticas de <a href="./../examples/lab02-gpio">entrada digital</a>, <a href="./../examples/lab03-uart">UART</a> y <a href="./../examples/lab04-adc">ADC</a> son ampliaciones. Se pueden realizar en una sesión adicional o sustituir una demostración cuando el instructor disponga de sus accesorios.</p><h2 id="preparacion-del-instructor" tabindex="-1">Preparación del instructor <a class="header-anchor" href="#preparacion-del-instructor" aria-label="Permalink to &quot;Preparación del instructor&quot;">​</a></h2><ol><li>Comprueba cada placa y programador con <a href="./../examples/lab01-blink">Blink</a>.</li><li>Instala Arduino IDE, el paquete UNIT Electronics PY32 0.1.7 y pyOCD.</li><li>Configura PY32F003x4, HSI a 24 MHz y VCC a 3.3 V.</li><li>Verifica los puentes de VCC y LED Enable.</li><li>Guarda fuentes, firmware de recuperación y resultados de esa estación.</li><li>Descarga los <a href="./../py32f003-getting-started/recursos">recursos de la placa</a> y los ejemplos para disponer de ellos localmente.</li></ol><p>La documentación se puede servir localmente sin conexión después de instalar sus dependencias. La instalación inicial del paquete Arduino y de pyOCD requiere conexión o herramientas previamente descargadas por el instructor.</p><h2 id="resultado-del-participante" tabindex="-1">Resultado del participante <a class="header-anchor" href="#resultado-del-participante" aria-label="Permalink to &quot;Resultado del participante&quot;">​</a></h2><ul><li>Un ejemplo modificado, compilado y cargado en su placa.</li><li>Un registro del consumo de memoria y la configuración empleada.</li><li>Una falla reproducida y corregida.</li><li>Evidencia del comportamiento esperado y de la recuperación tras reset.</li></ul>`,13)])])}const h=e(n,[["render",o]]);export{m as __pageData,h as default};
